class Solution:
    def baseNeg2(self, n: int) -> str:
        if n == 0:
            return "0"
        digits = []
        while n != 0:
            r = n & 1
            digits.append(str(r))
            n = (n - r) // -2
        return ''.join(reversed(digits))

c.cpp:
class Solution {
public:
    string baseNeg2(int n) {
        if (n == 0) return "0";
        string res;
        while (n != 0) {
            int r = n & 1;
            res += ('0' + r);
            n = (n - r) / -2;
        }
        reverse(res.begin(), res.end());
        return res;
    }
};

